import React, { useCallback, useEffect, useState } from "react";
import axios from "axios";

import { API_URL } from "../apiConfig";
import { formatMoney } from "../marketConfig";
import { useDriverContext } from "./context/DriverContext";

// ─── Yala Branding Colors ───────────────────────────────────────────────────
const COLORS = {
  primaryGreen: "#00A651",
  goldAccent: "#D4AF37",
  darkNavy: "#0B1220",
  white: "#FFFFFF",
  cardBg: "#111827",
  textMuted: "#9CA3AF",
};

// ─── Main Component ─────────────────────────────────────────────────────────
export default function DriverRideHistory() {
  const token = localStorage.getItem("access");
  const { state } = useDriverContext();
  const [rides, setRides] = useState([]);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(false);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState("");
  const [dateFrom, setDateFrom] = useState("");
  const [dateTo, setDateTo] = useState("");

  const fetchRides = useCallback(async () => {
    try {
      setLoading(true);
      const params = new URLSearchParams({ page: String(page) });
      if (statusFilter) params.append("status", statusFilter);
      if (dateFrom) params.append("date_from", dateFrom);
      if (dateTo) params.append("date_to", dateTo);

      const response = await axios.get(
        `${API_URL}/drivers/me/rides/?${params.toString()}`,
        { headers: { Authorization: `Bearer ${token}` } }
      );

      const data = response.data;
      const results = Array.isArray(data) ? data : data.results || [];
      setRides(results);
      setHasMore(Boolean(data.next));
    } catch (error) {
      console.log("Ride history fetch error:", error.response?.data || error);
    } finally {
      setLoading(false);
    }
  }, [token, page, statusFilter, dateFrom, dateTo]);

  useEffect(() => {
    fetchRides();
  }, [fetchRides]);

  const getStatusColor = (status) => {
    switch (status) {
      case "completed": return "#10B981";
      case "cancelled": return "#EF4444";
      case "in_progress": return COLORS.goldAccent;
      default: return COLORS.textMuted;
    }
  };

  return (
    <div style={containerStyle}>
      <header style={headerStyle}>
        <h1 style={titleStyle}>Ride History</h1>
      </header>

      {/* Filters */}
      <div style={filtersStyle}>
        <select
          value={statusFilter}
          onChange={(e) => { setStatusFilter(e.target.value); setPage(1); }}
          style={selectStyle}
          aria-label="Filter by status"
        >
          <option value="">All statuses</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
          <option value="in_progress">In Progress</option>
        </select>
        <input
          type="date"
          value={dateFrom}
          onChange={(e) => { setDateFrom(e.target.value); setPage(1); }}
          style={dateInputStyle}
          aria-label="From date"
        />
        <input
          type="date"
          value={dateTo}
          onChange={(e) => { setDateTo(e.target.value); setPage(1); }}
          style={dateInputStyle}
          aria-label="To date"
        />
      </div>

      {loading ? (
        <div style={loadingStyle}>Loading ride history...</div>
      ) : rides.length === 0 ? (
        <div style={emptyStyle}>
          <span style={emptyIconStyle}>🚗</span>
          <p style={emptyTextStyle}>No rides found.</p>
          <p style={emptySubtextStyle}>Your completed rides will appear here.</p>
        </div>
      ) : (
        <div style={listStyle}>
          {rides.map((ride) => (
            <div key={ride.id} style={rideCardStyle}>
              <div style={rideHeaderStyle}>
                <span style={rideDateStyle}>
                  {ride.created_at
                    ? new Date(ride.created_at).toLocaleDateString()
                    : ""}
                </span>
                <span style={{ ...rideStatusStyle, color: getStatusColor(ride.status) }}>
                  {ride.status}
                </span>
              </div>
              <div style={rideBodyStyle}>
                <div style={locationRowStyle}>
                  <span style={dotPickupStyle} />
                  <span style={locationTextStyle}>{ride.pickup_address || ride.pickup || "Pickup"}</span>
                </div>
                <div style={locationRowStyle}>
                  <span style={dotDropoffStyle} />
                  <span style={locationTextStyle}>{ride.destination_address || ride.destination || "Destination"}</span>
                </div>
              </div>
              <div style={rideFareStyle}>
                {formatMoney(ride.fare || ride.driver_earning || 0)}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Pagination */}
      <div style={paginationStyle}>
        <button
          onClick={() => setPage((p) => Math.max(1, p - 1))}
          disabled={page <= 1}
          style={{ ...pageButtonStyle, opacity: page <= 1 ? 0.4 : 1 }}
        >
          Previous
        </button>
        <span style={pageInfoStyle}>Page {page}</span>
        <button
          onClick={() => setPage((p) => p + 1)}
          disabled={!hasMore}
          style={{ ...pageButtonStyle, opacity: !hasMore ? 0.4 : 1 }}
        >
          Next
        </button>
      </div>
    </div>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────
const containerStyle = {
  minHeight: "100vh",
  backgroundColor: COLORS.darkNavy,
  padding: "20px 16px 100px",
  fontFamily: "'Plus Jakarta Sans', Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
};

const headerStyle = {
  marginBottom: "20px",
};

const titleStyle = {
  color: COLORS.white,
  fontSize: "24px",
  fontWeight: "800",
  margin: 0,
};

const filtersStyle = {
  display: "flex",
  gap: "8px",
  marginBottom: "16px",
  flexWrap: "wrap",
};

const selectStyle = {
  flex: "1 1 120px",
  padding: "10px 12px",
  borderRadius: "12px",
  border: "1px solid rgba(255,255,255,0.12)",
  background: "#111827",
  color: COLORS.white,
  fontSize: "13px",
};

const dateInputStyle = {
  flex: "1 1 120px",
  padding: "10px 12px",
  borderRadius: "12px",
  border: "1px solid rgba(255,255,255,0.12)",
  background: "#111827",
  color: COLORS.white,
  fontSize: "13px",
};

const loadingStyle = {
  color: COLORS.textMuted,
  textAlign: "center",
  padding: "60px 20px",
  fontSize: "15px",
};

const emptyStyle = {
  textAlign: "center",
  padding: "60px 20px",
};

const emptyIconStyle = {
  fontSize: "48px",
  display: "block",
  marginBottom: "16px",
};

const emptyTextStyle = {
  color: COLORS.white,
  fontSize: "16px",
  fontWeight: "600",
  margin: "0 0 8px",
};

const emptySubtextStyle = {
  color: COLORS.textMuted,
  fontSize: "14px",
  margin: 0,
};

const listStyle = {
  display: "flex",
  flexDirection: "column",
  gap: "10px",
};

const rideCardStyle = {
  background: COLORS.cardBg,
  borderRadius: "16px",
  padding: "14px 16px",
  border: "1px solid rgba(255,255,255,0.08)",
};

const rideHeaderStyle = {
  display: "flex",
  justifyContent: "space-between",
  alignItems: "center",
  marginBottom: "10px",
};

const rideDateStyle = {
  color: COLORS.textMuted,
  fontSize: "12px",
};

const rideStatusStyle = {
  fontSize: "12px",
  fontWeight: "800",
  textTransform: "capitalize",
};

const rideBodyStyle = {
  display: "flex",
  flexDirection: "column",
  gap: "6px",
  marginBottom: "10px",
};

const locationRowStyle = {
  display: "flex",
  alignItems: "center",
  gap: "8px",
};

const dotPickupStyle = {
  width: "8px",
  height: "8px",
  borderRadius: "50%",
  background: COLORS.primaryGreen,
  flexShrink: 0,
};

const dotDropoffStyle = {
  width: "8px",
  height: "8px",
  borderRadius: "50%",
  background: COLORS.goldAccent,
  flexShrink: 0,
};

const locationTextStyle = {
  color: COLORS.white,
  fontSize: "13px",
  overflow: "hidden",
  textOverflow: "ellipsis",
  whiteSpace: "nowrap",
};

const rideFareStyle = {
  color: COLORS.primaryGreen,
  fontSize: "16px",
  fontWeight: "800",
  textAlign: "right",
};

const paginationStyle = {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  gap: "16px",
  marginTop: "20px",
};

const pageButtonStyle = {
  padding: "10px 18px",
  borderRadius: "999px",
  border: "1px solid rgba(255,255,255,0.12)",
  background: "#111827",
  color: COLORS.white,
  fontSize: "13px",
  fontWeight: "700",
  cursor: "pointer",
};

const pageInfoStyle = {
  color: COLORS.textMuted,
  fontSize: "13px",
};
